from typing import List

def parse_music(music_string: str) -> List[int]:
    note_lengths = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split()
    result = []

    for note in notes:
        if note in note_lengths:
            result.append(note_lengths[note])

    return result

